<script setup lang="ts">
import { Head, router, useForm } from '@inertiajs/vue3'
import { ref } from 'vue'
const props=defineProps<{users:{data:any[];total:number};stats:Record<string,number>;thresholds:any;filters:any;history:any[]}>()
const search=ref(props.filters.search||''),category=ref(props.filters.category||'')
const trend=()=>props.history.map((x,i)=>{const max=Math.max(1,...props.history.map(y=>Number(y.users_count)));return (i*100/(props.history.length-1||1))+','+(100-Number(x.users_count)*100/max)}).join(' ')\nconst apply=()=>router.get('/activity',{search:search.value,category:category.value},{preserveState:true})
const form=useForm({heavy_min_messages:props.thresholds?.heavy_min_messages||1000,active_min_messages:props.thresholds?.active_min_messages||100,low_active_min_messages:props.thresholds?.low_active_min_messages||10,dormant_days:props.thresholds?.dormant_days||30,suspicious_new_account_days:props.thresholds?.suspicious_new_account_days||1,suspicious_messages_per_hour:props.thresholds?.suspicious_messages_per_hour||5000})
</script>
<template><Head title="فعالیت کاربران"/><v-container fluid class="pa-6"><h1 class="text-h4 mb-5">فعالیت کاربران</h1><v-row><v-col v-for="key in ['heavy_active','active','low_active','dormant','suspicious']" :key="key" cols="6" md="2"><v-card rounded="xl" class="pa-4"><div class="text-caption">{{ key }}</div><div class="text-h4">{{ stats[key]||0 }}</div></v-card></v-col></v-row><v-card rounded="xl" class="pa-4 mt-5"><v-card-title>روند دسته‌بندی کاربران</v-card-title><svg v-if="history.length" viewBox="0 0 100 100" preserveAspectRatio="none" width="100%" height="100"><polyline :points="trend()" fill="none" stroke="currentColor" stroke-width="1.5" vector-effect="non-scaling-stroke"/></svg><v-alert type="info" variant="tonal" class="my-3">برای شمارش دقیق پیام‌ها، اتصال read-only دیتابیس Synapse با SYNAPSE_DB_URL لازم است.</v-alert><v-row><v-col cols="12" md="5"><v-text-field v-model="search" label="جستجوی شناسه"/></v-col><v-col cols="12" md="4"><v-select v-model="category" label="دسته" :items="['','heavy_active','active','low_active','dormant','suspicious']"/></v-col><v-col cols="12" md="3"><v-btn color="primary" block @click="apply">اعمال فیلتر</v-btn></v-col></v-row><v-table><thead><tr><th>کاربر</th><th>آخرین فعالیت</th><th>تعداد پیام</th><th>مدیا (بایت)</th><th>دسته</th></tr></thead><tbody><tr v-for="u in users.data" :key="u.user_id"><td>{{ u.user_id }}</td><td>{{ u.last_seen_at||'—' }}</td><td>{{ u.message_count }}</td><td>{{ u.media_bytes }}</td><td><v-chip size="small">{{ u.category }}</v-chip></td></tr></tbody></v-table></v-card><v-card rounded="xl" class="pa-5 mt-5"><v-card-title>تنظیم آستانه‌های دسته‌بندی</v-card-title><v-form @submit.prevent="form.put('/activity/thresholds')"><v-row><v-col cols="6" md="4"><v-text-field v-model.number="form.heavy_min_messages" type="number" label="فعال سنگین: حداقل پیام"/></v-col><v-col cols="6" md="4"><v-text-field v-model.number="form.active_min_messages" type="number" label="فعال: حداقل پیام"/></v-col><v-col cols="6" md="4"><v-text-field v-model.number="form.low_active_min_messages" type="number" label="کم‌فعال: حداقل پیام"/></v-col><v-col cols="6" md="4"><v-text-field v-model.number="form.dormant_days" type="number" label="خوابیده: روز بدون فعالیت"/></v-col><v-col cols="6" md="4"><v-text-field v-model.number="form.suspicious_new_account_days" type="number" label="حساب جدید مشکوک (روز)"/></v-col><v-col cols="6" md="4"><v-text-field v-model.number="form.suspicious_messages_per_hour" type="number" label="پیام مشکوک در ساعت"/></v-col></v-row><v-btn color="primary" type="submit">ذخیره تنظیمات</v-btn></v-form></v-card></v-container></template>
